// Download the 26 missing roguelite trainer skins.
//
// 1. Open any https://www.planetminecraft.com/ page in your browser.
// 2. Open the console (Cmd-Option-J) and paste this whole file.
// 3. Chrome asks once to "allow multiple downloads" — allow it.
// 4. Move the files into ops/skin-staging/ and run:
//        python3 ops/install_hand_sourced_skins.py
//
// Generated by ops/gen_skin_fetch_snippet.py from ops/roguelite-missing-skins.md.
// Must run ON the planetminecraft origin: the fetch needs the site's own cookies, which is
// what distinguishes it from an automated request the Cloudflare WAF rejects.

(async () => {
  const SKINS = [
  ["Acerola.png", "/skin/acerola-5729551/download/file/16137530/"],
  ["Allister.png", "/skin/allister/download/file/12268069/"],
  ["Bede.png", "/skin/bede-pokemon-sw-sh/download/file/12533145/"],
  ["Blue.png", "/skin/pokemon-champion-blue-pokemon-sun-moon/download/file/11197001/"],
  ["Geeta.png", "/skin/pokemon-geeta/download/file/17088253/"],
  ["Gordie.png", "/skin/t1-5653864/download/file/15909190/"],
  ["Grimsley.png", "/skin/grimsley-pokemon-bw/download/file/14325163/"],
  ["Grusha.png", "/skin/grusha-pokemon/download/file/16402973/"],
  ["Ilima.png", "/skin/ilima-pokemon-sun-and-moon-a-lot-better-in-3d-oof/download/file/11620324/"],
  ["Iris.png", "/skin/champion-iris-pokemon-6236933/download/file/17671729/"],
  ["Karen.png", "/skin/karen-5092265/download/file/14325173/"],
  ["Katy.png", "/skin/pokemon-scarlet-amp-violet-gym-leader-katy/download/file/19832473/"],
  ["Kiawe.png", "/skin/kiawe/download/file/12475957/"],
  ["Kukui.png", "/skin/professor-kukui-pokemon-sun-and-moon/download/file/11790939/"],
  ["Lana.png", "/skin/lana-pok-mon/download/file/16334895/"],
  ["Malva.png", "/skin/elite-four-malva/download/file/7430294/"],
  ["Mina.png", "/skin/mina---pokemon-sunmoon/download/file/10763377/"],
  ["Olivia.png", "/skin/olivia-6190586/download/file/17528550/"],
  ["Olympia.png", "/skin/gym-leader-olympia/download/file/7421938/"],
  ["Phoebe.png", "/skin/phoebe-from-pokemon/download/file/10371242/"],
  ["Piers.png", "/skin/piers/download/file/12553553/"],
  ["Raihan.png", "/skin/raihan-pokemon/download/file/13959617/"],
  ["Ramos.png", "/skin/gym-leader-ramos/download/file/7420705/"],
  ["Steven.png", "/skin/steven-stone-pokemon-4278008/download/file/12089666/"],
  ["Tulip.png", "/skin/tulip-6655537/download/file/18929376/"],
  ["Wulfric.png", "/skin/gym-leader-wulfric/download/file/7422486/"]
  ];

  // A real 64x64 skin is well under 10 KB. Anything larger came back as a page rather than
  // an image, which is exactly the failure this script exists to avoid — so it is reported
  // instead of being saved under a .png name.
  const MAX_BYTES = 20000;
  const ok = [], bad = [];

  for (const [name, path] of SKINS) {
    try {
      const res = await fetch(path, { credentials: "include" });
      if (!res.ok) { bad.push(`${name}: HTTP ${res.status}`); continue; }
      const blob = await res.blob();
      if (blob.size > MAX_BYTES) { bad.push(`${name}: ${blob.size} bytes, not an image`); continue; }

      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = name;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
      ok.push(`${name} (${blob.size} B)`);
    } catch (e) {
      bad.push(`${name}: ${e.message}`);
    }
    // Spaced out so 26 requests in a row do not look like the thing the WAF blocks.
    await new Promise((r) => setTimeout(r, 700));
  }

  console.log(`%cdownloaded ${ok.length}/${SKINS.length}`, "font-weight:bold");
  ok.forEach((s) => console.log("  " + s));
  if (bad.length) {
    console.warn(`failed ${bad.length}:`);
    bad.forEach((s) => console.warn("  " + s));
  }
})();
